function tryParseTnlPayload(input: string, fileName?: string): {
  decryptedJson: Record<string, any>;
  encryptionMethod: string;
} | null {
  const trimmed = input.trim();
  let bytes: Buffer | null = null;

  if (trimmed.startsWith('T1BMA') || /^[A-Za-z0-9+/=]{80,}$/.test(trimmed)) {
    try {
      const buf = Buffer.from(trimmed, 'base64');
      if (buf.length >= 12 && buf[0] === 0x4f && buf[1] === 0x50 && buf[2] === 0x4c && buf[3] === 0x02) {
        bytes = buf;
      }
    } catch { }
  }

  if (!bytes && /^4f504c02/i.test(trimmed)) {
    try {
      const buf = Buffer.from(trimmed, 'hex');
      if (buf.length >= 12 && buf[0] === 0x4f && buf[1] === 0x50 && buf[2] === 0x4c && buf[3] === 0x02) {
        bytes = buf;
      }
    } catch { }
  }

  if (!bytes && trimmed.length >= 12 && trimmed.charCodeAt(0) === 0x4f && trimmed.charCodeAt(1) === 0x50 && trimmed.charCodeAt(2) === 0x4c && trimmed.charCodeAt(3) === 0x02) {
    bytes = Buffer.from(trimmed, 'binary');
  }

  if (!bytes && trimmed.includes('<properties>') && trimmed.includes('<entry key=')) {
    const props = parseOpenTunnelXmlProperties(trimmed);
    if (props && Object.keys(props).length > 0) {
      return buildOpenTunnelRouteResponse(props, trimmed, fileName || 'opentunnel.tnl', trimmed.length);
    }
  }

  if (!bytes) return null;

  try {
    const rawLen = (bytes[4] & 0xff) | ((bytes[5] & 0xff) << 8) | ((bytes[6] & 0xff) << 16) | ((bytes[7] & 0xff) << 24);
    const len = (rawLen ^ 0xa7b3c5d1) >>> 0;
    if (len <= 0 || len > bytes.length - 12) return null;

    const out = Buffer.alloc(len);
    const base = 195;
    for (let i = 0; i < len; i++) {
      const k = i % 8;
      const rot = (k === 0) ? base : (((base << k) | (base >>> (8 - k))) & 0xff);
      out[i] = (bytes[i + 12] ^ rot ^ (i & 0xff)) & 0xff;
    }

    const payloadStr = out.toString('utf8');
    const parts = payloadStr.split('.');
    if (parts.length < 3) return null;

    const salt = Buffer.from(parts[0], 'base64');
    const iv = Buffer.from(parts[1], 'base64');
    const cipherAndTag = Buffer.from(parts[2], 'base64');

    const decryptedXml = decryptOpenTunnelPayloadSync(salt, iv, cipherAndTag);
    if (!decryptedXml || !decryptedXml.includes('<properties>')) return null;

    const props = parseOpenTunnelXmlProperties(decryptedXml);
    let hexPreview = '';
    for (let i = 0; i < Math.min(bytes.length, 32); i++) {
      hexPreview += bytes[i].toString(16).padStart(2, '0');
    }

    return buildOpenTunnelRouteResponse(props, decryptedXml, fileName || 'opentunnel.tnl', bytes.length, hexPreview);
  } catch (err: any) {
    return null;
  }
}

